def test_median():
    assert solution.percentile([1, 2, 3, 4], 50) == 2.0

def test_p95():
    assert solution.percentile(list(range(1, 21)), 95) == 19.0

def test_max():
    assert solution.percentile([5, 1, 9], 100) == 9.0

def test_unsorted():
    assert solution.percentile([9, 1, 5], 50) == 5.0

def test_empty():
    try:
        solution.percentile([], 50)
    except ValueError:
        return
    raise AssertionError("expected ValueError")

def test_invalid_q():
    for q in (0, -1, 101):
        try:
            solution.percentile([1, 2], q)
        except ValueError:
            continue
        raise AssertionError("expected ValueError")

def test_returns_float():
    assert isinstance(solution.percentile([1, 2], 50), float)
